<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue';defineProps<{open:boolean,count:number}>();const emit=defineEmits(['close']);const fps=ref(0),lcp=ref('—'),cls=ref('0.000'),weight=ref(0),dom=ref(0);let frame=0,last=0,ticks=0,observers:PerformanceObserver[]=[];onMounted(()=>{function update(t:number){ticks++;if(t-last>1000){fps.value=ticks;ticks=0;last=t;dom.value=document.getElementsByTagName('*').length;weight.value=Math.round((performance.getEntriesByType('resource') as PerformanceResourceTiming[]).reduce((a,e)=>a+e.transferSize,0)/1024)}frame=requestAnimationFrame(update)}frame=requestAnimationFrame(update);try{const a=new PerformanceObserver(l=>{const es=l.getEntries();lcp.value=Math.round(es[es.length-1].startTime)+' ms'});a.observe({type:'largest-contentful-paint',buffered:true});observers.push(a);let v=0;const b=new PerformanceObserver(l=>{for(const e of l.getEntries() as any[])if(!e.hadRecentInput)v+=e.value;cls.value=v.toFixed(3)});b.observe({type:'layout-shift',buffered:true});observers.push(b)}catch{}});onUnmounted(()=>{cancelAnimationFrame(frame);observers.forEach(o=>o.disconnect())});
</script><template><aside v-if="open" class="hud" aria-label="Live browser telemetry"><header>LIVE INSPECTOR <button @click="emit('close')" aria-label="Close inspector">×</button></header><div class="metrics"><span>LCP <b>{{lcp}}</b></span><span>CLS <b>{{cls}}</b></span><span>TRANSFER <b>{{weight}} KB</b></span><span>FPS <b>{{fps}}</b></span><span>PARTICLES <b>{{count}}</b></span><span>DOM NODES <b>{{dom}}</b></span></div><pre><code><span>const</span> t = THREE.MathUtils.clamp(
  (scrollY - start) / (end - start), 0, 1
)
const eased = t * t * (3 - 2 * t)</code></pre></aside></template>
